-- Reviewed historical promotion. Staging stays private; no workers or external dispatch.
BEGIN;
SET LOCAL lock_timeout='10s';
SET LOCAL statement_timeout='90s';
DO $promotion$
DECLARE pid uuid:='2e91ac73-af2d-410b-860c-b7e249212408'; saved wholesale_ingest.onboarding_promotions; owner_id uuid:='89f3b3f6-5a88-4b79-b3f4-461e0cd626a2'; n integer;
BEGIN
 PERFORM pg_advisory_xact_lock(hashtextextended('onboarding-promotion:'||pid::text,0));
 SELECT * INTO STRICT saved FROM wholesale_ingest.onboarding_promotions WHERE id=pid FOR UPDATE;
 IF saved.state='complete' THEN RETURN; END IF;
 IF saved.source_project<>'tbhwxgfzbiaqjurghntj' OR saved.operator_id<>owner_id THEN RAISE EXCEPTION 'Promotion identity mismatch'; END IF;
 IF (SELECT count(*) FROM wholesale_ingest.onboarding_promotion_parts WHERE promotion_id=pid)<>27 THEN RAISE EXCEPTION 'Incomplete staged graph'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=owner_id AND status='approved' AND role='admin')
 OR NOT EXISTS(SELECT 1 FROM public.app_settings WHERE key='lead_owner_user_id' AND value=owner_id::text)
 THEN RAISE EXCEPTION 'Approved owner configuration changed'; END IF;
 IF EXISTS(SELECT 1 FROM wholesale_ingest.sources WHERE enabled)
 OR EXISTS(SELECT 1 FROM wholesale_ingest.settings WHERE outreach_enabled OR daily_trace_cap_cents<>0)
 OR (SELECT enabled FROM private.retell_sms_scheduler WHERE singleton)
 THEN RAISE EXCEPTION 'Collection, spending and messaging must remain disabled'; END IF;
 IF NOT EXISTS(SELECT 1 FROM wholesale_ingest.sources WHERE id='0151c152-417d-4e95-8482-7113e469c10f' AND source_key='tx-collin-pre_foreclosure' AND NOT enabled)
 THEN RAISE EXCEPTION 'Source mapping changed'; END IF;
 LOCK TABLE public.leads IN SHARE ROW EXCLUSIVE MODE;
 LOCK TABLE public.tasks IN SHARE ROW EXCLUSIVE MODE;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements((SELECT source_payload FROM wholesale_ingest.onboarding_promotion_parts WHERE promotion_id=pid AND entity='existing_leads')) v
 LEFT JOIN public.leads l ON l.id=(v->>'id')::uuid WHERE to_jsonb(l) IS DISTINCT FROM v)
 THEN RAISE EXCEPTION 'Existing CRM lead changed since snapshot'; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_populate_recordset(NULL::public.leads,(SELECT target_payload FROM wholesale_ingest.onboarding_promotion_parts WHERE promotion_id=pid AND entity='public.leads')) s
 JOIN public.leads l ON (lower(regexp_replace(trim(s.property_address),'\s+',' ','g'))||'|'||lower(trim(s.city))||'|'||upper(coalesce(s.state,'TX')))=(lower(regexp_replace(trim(l.property_address),'\s+',' ','g'))||'|'||lower(trim(l.city))||'|'||upper(coalesce(l.state,'TX'))))
 THEN RAISE EXCEPTION 'New lead collides with existing CRM identity'; END IF;
 IF (SELECT md5(coalesce(jsonb_agg(v ORDER BY v::text),'[]')::text) FROM wholesale_ingest.onboarding_promotion_parts p CROSS JOIN LATERAL jsonb_array_elements(p.source_payload) v WHERE p.promotion_id=pid AND p.entity='public.leads')<>'53a7792951dcc0f41b426856de1f7af0' THEN RAISE EXCEPTION 'Source checksum mismatch: public.leads'; END IF;
 IF (SELECT md5(coalesce(jsonb_agg(v ORDER BY v::text),'[]')::text) FROM wholesale_ingest.onboarding_promotion_parts p CROSS JOIN LATERAL jsonb_array_elements(p.source_payload) v WHERE p.promotion_id=pid AND p.entity='public.tasks')<>'75526b609e9376af6e5a02f07206602c' THEN RAISE EXCEPTION 'Source checksum mismatch: public.tasks'; END IF;
 IF (SELECT md5(coalesce(jsonb_agg(v ORDER BY v::text),'[]')::text) FROM wholesale_ingest.onboarding_promotion_parts p CROSS JOIN LATERAL jsonb_array_elements(p.source_payload) v WHERE p.promotion_id=pid AND p.entity='wholesale_ingest.ingest_runs')<>'ac1bfdceec9f102061ddaa02421cf319' THEN RAISE EXCEPTION 'Source checksum mismatch: wholesale_ingest.ingest_runs'; END IF;
 IF (SELECT md5(coalesce(jsonb_agg(v ORDER BY v::text),'[]')::text) FROM wholesale_ingest.onboarding_promotion_parts p CROSS JOIN LATERAL jsonb_array_elements(p.source_payload) v WHERE p.promotion_id=pid AND p.entity='wholesale_ingest.raw_payloads')<>'ea51fd5a81d9d83ab0404c1fc5cadc9b' THEN RAISE EXCEPTION 'Source checksum mismatch: wholesale_ingest.raw_payloads'; END IF;
 IF (SELECT md5(coalesce(jsonb_agg(v ORDER BY v::text),'[]')::text) FROM wholesale_ingest.onboarding_promotion_parts p CROSS JOIN LATERAL jsonb_array_elements(p.source_payload) v WHERE p.promotion_id=pid AND p.entity='wholesale_ingest.properties')<>'91250d24d4805f000ac55aa70f5465b5' THEN RAISE EXCEPTION 'Source checksum mismatch: wholesale_ingest.properties'; END IF;
 IF (SELECT md5(coalesce(jsonb_agg(v ORDER BY v::text),'[]')::text) FROM wholesale_ingest.onboarding_promotion_parts p CROSS JOIN LATERAL jsonb_array_elements(p.source_payload) v WHERE p.promotion_id=pid AND p.entity='wholesale_ingest.records')<>'9279b075d8929923ed073a46d2aee20f' THEN RAISE EXCEPTION 'Source checksum mismatch: wholesale_ingest.records'; END IF;
 IF (SELECT md5(coalesce(jsonb_agg(v ORDER BY v::text),'[]')::text) FROM wholesale_ingest.onboarding_promotion_parts p CROSS JOIN LATERAL jsonb_array_elements(p.source_payload) v WHERE p.promotion_id=pid AND p.entity='wholesale_ingest.review_events')<>'1181b84bc75d8dc60c7583bf0d70ccb1' THEN RAISE EXCEPTION 'Source checksum mismatch: wholesale_ingest.review_events'; END IF;
 IF (SELECT md5(coalesce(jsonb_agg(v ORDER BY v::text),'[]')::text) FROM wholesale_ingest.onboarding_promotion_parts p CROSS JOIN LATERAL jsonb_array_elements(p.source_payload) v WHERE p.promotion_id=pid AND p.entity='wholesale_ingest.property_aliases')<>'c50f1a148a76dc3f7cd6cebd116be817' THEN RAISE EXCEPTION 'Source checksum mismatch: wholesale_ingest.property_aliases'; END IF;
 IF (SELECT md5(coalesce(jsonb_agg(v ORDER BY v::text),'[]')::text) FROM wholesale_ingest.onboarding_promotion_parts p CROSS JOIN LATERAL jsonb_array_elements(p.source_payload) v WHERE p.promotion_id=pid AND p.entity='wholesale_ingest.distress_signals')<>'dad7b3d2c5b2e856d8c1de7c17b63c85' THEN RAISE EXCEPTION 'Source checksum mismatch: wholesale_ingest.distress_signals'; END IF;
 IF (SELECT md5(coalesce(jsonb_agg(v ORDER BY v::text),'[]')::text) FROM wholesale_ingest.onboarding_promotion_parts p CROSS JOIN LATERAL jsonb_array_elements(p.source_payload) v WHERE p.promotion_id=pid AND p.entity='wholesale_ingest.signal_observations')<>'608a2f0c78c811a1d5a8cbdc3b9407a2' THEN RAISE EXCEPTION 'Source checksum mismatch: wholesale_ingest.signal_observations'; END IF;
 IF (SELECT md5(coalesce(jsonb_agg(v ORDER BY v::text),'[]')::text) FROM wholesale_ingest.onboarding_promotion_parts p CROSS JOIN LATERAL jsonb_array_elements(p.source_payload) v WHERE p.promotion_id=pid AND p.entity='wholesale_ingest.skip_trace_requests')<>'8cdc3a3ccab8bc05e9557d61ee1fd852' THEN RAISE EXCEPTION 'Source checksum mismatch: wholesale_ingest.skip_trace_requests'; END IF;
 IF (SELECT md5(coalesce(jsonb_agg(v ORDER BY v::text),'[]')::text) FROM wholesale_ingest.onboarding_promotion_parts p CROSS JOIN LATERAL jsonb_array_elements(p.source_payload) v WHERE p.promotion_id=pid AND p.entity='wholesale_ingest.contacts')<>'be7d0328113928af85dcb0d98b4e591f' THEN RAISE EXCEPTION 'Source checksum mismatch: wholesale_ingest.contacts'; END IF;
 IF (SELECT md5(coalesce(jsonb_agg(v ORDER BY v::text),'[]')::text) FROM wholesale_ingest.onboarding_promotion_parts p CROSS JOIN LATERAL jsonb_array_elements(p.source_payload) v WHERE p.promotion_id=pid AND p.entity='wholesale_ingest.propstream_handoffs')<>'4c0ee895c9d8138ca53f15161d9de20b' THEN RAISE EXCEPTION 'Source checksum mismatch: wholesale_ingest.propstream_handoffs'; END IF;
 IF (SELECT md5(coalesce(jsonb_agg(v ORDER BY v::text),'[]')::text) FROM wholesale_ingest.onboarding_promotion_parts p CROSS JOIN LATERAL jsonb_array_elements(p.source_payload) v WHERE p.promotion_id=pid AND p.entity='wholesale_ingest.propstream_events')<>'3278f33d7c8e60e9dc80c824349c2c42' THEN RAISE EXCEPTION 'Source checksum mismatch: wholesale_ingest.propstream_events'; END IF;
 IF (SELECT md5(coalesce(jsonb_agg(v ORDER BY v::text),'[]')::text) FROM wholesale_ingest.onboarding_promotion_parts p CROSS JOIN LATERAL jsonb_array_elements(p.source_payload) v WHERE p.promotion_id=pid AND p.entity='wholesale_ingest.trace_operator_events')<>'d751713988987e9331980363e24189ce' THEN RAISE EXCEPTION 'Source checksum mismatch: wholesale_ingest.trace_operator_events'; END IF;
 IF (SELECT md5(coalesce(jsonb_agg(v ORDER BY v::text),'[]')::text) FROM wholesale_ingest.onboarding_promotion_parts p CROSS JOIN LATERAL jsonb_array_elements(p.source_payload) v WHERE p.promotion_id=pid AND p.entity='wholesale_ingest.daily_budgets')<>'4ba8d1bc4df3c0da3493d8865e7d5704' THEN RAISE EXCEPTION 'Source checksum mismatch: wholesale_ingest.daily_budgets'; END IF;
 IF (SELECT md5(coalesce(jsonb_agg(v ORDER BY v::text),'[]')::text) FROM wholesale_ingest.onboarding_promotion_parts p CROSS JOIN LATERAL jsonb_array_elements(p.source_payload) v WHERE p.promotion_id=pid AND p.entity='wholesale_ingest.foreclosure_first_seen')<>'a6af7b0b708dc77d93524d5eb48c031c' THEN RAISE EXCEPTION 'Source checksum mismatch: wholesale_ingest.foreclosure_first_seen'; END IF;
 IF (SELECT md5(coalesce(jsonb_agg(v ORDER BY v::text),'[]')::text) FROM wholesale_ingest.onboarding_promotion_parts p CROSS JOIN LATERAL jsonb_array_elements(p.source_payload) v WHERE p.promotion_id=pid AND p.entity='wholesale_ingest.foreclosure_captures')<>'2b2e2453ab0a5e9d3706b8a1b8902d6f' THEN RAISE EXCEPTION 'Source checksum mismatch: wholesale_ingest.foreclosure_captures'; END IF;
 IF (SELECT md5(coalesce(jsonb_agg(v ORDER BY v::text),'[]')::text) FROM wholesale_ingest.onboarding_promotion_parts p CROSS JOIN LATERAL jsonb_array_elements(p.source_payload) v WHERE p.promotion_id=pid AND p.entity='wholesale_ingest.foreclosure_extractions')<>'6b9fd61cdad0c5e41a521503779cd15f' THEN RAISE EXCEPTION 'Source checksum mismatch: wholesale_ingest.foreclosure_extractions'; END IF;
 IF (SELECT md5(coalesce(jsonb_agg(v ORDER BY v::text),'[]')::text) FROM wholesale_ingest.onboarding_promotion_parts p CROSS JOIN LATERAL jsonb_array_elements(p.source_payload) v WHERE p.promotion_id=pid AND p.entity='wholesale_ingest.foreclosure_batches')<>'67ff3811e2df20db3a872e6858a5cf07' THEN RAISE EXCEPTION 'Source checksum mismatch: wholesale_ingest.foreclosure_batches'; END IF;
 IF (SELECT md5(coalesce(jsonb_agg(v ORDER BY v::text),'[]')::text) FROM wholesale_ingest.onboarding_promotion_parts p CROSS JOIN LATERAL jsonb_array_elements(p.source_payload) v WHERE p.promotion_id=pid AND p.entity='wholesale_ingest.foreclosure_appraisal_batches')<>'d751713988987e9331980363e24189ce' THEN RAISE EXCEPTION 'Source checksum mismatch: wholesale_ingest.foreclosure_appraisal_batches'; END IF;
 IF (SELECT md5(coalesce(jsonb_agg(v ORDER BY v::text),'[]')::text) FROM wholesale_ingest.onboarding_promotion_parts p CROSS JOIN LATERAL jsonb_array_elements(p.source_payload) v WHERE p.promotion_id=pid AND p.entity='wholesale_ingest.propstream_batches')<>'01a7ec2af1553438ea0fd432a35d1614' THEN RAISE EXCEPTION 'Source checksum mismatch: wholesale_ingest.propstream_batches'; END IF;
 IF (SELECT md5(coalesce(jsonb_agg(v ORDER BY v::text),'[]')::text) FROM wholesale_ingest.onboarding_promotion_parts p CROSS JOIN LATERAL jsonb_array_elements(p.source_payload) v WHERE p.promotion_id=pid AND p.entity='wholesale_ingest.propstream_external_submissions')<>'c943ebf6050aa61ac4229bd0168f4df0' THEN RAISE EXCEPTION 'Source checksum mismatch: wholesale_ingest.propstream_external_submissions'; END IF;
 IF (SELECT md5(coalesce(jsonb_agg(v ORDER BY v::text),'[]')::text) FROM wholesale_ingest.onboarding_promotion_parts p CROSS JOIN LATERAL jsonb_array_elements(p.source_payload) v WHERE p.promotion_id=pid AND p.entity='wholesale_ingest.lead_evaluations')<>'d751713988987e9331980363e24189ce' THEN RAISE EXCEPTION 'Source checksum mismatch: wholesale_ingest.lead_evaluations'; END IF;
 IF (SELECT md5(coalesce(jsonb_agg(v ORDER BY v::text),'[]')::text) FROM wholesale_ingest.onboarding_promotion_parts p CROSS JOIN LATERAL jsonb_array_elements(p.source_payload) v WHERE p.promotion_id=pid AND p.entity='wholesale_ingest.scoring_jobs')<>'d751713988987e9331980363e24189ce' THEN RAISE EXCEPTION 'Source checksum mismatch: wholesale_ingest.scoring_jobs'; END IF;
