 IF EXISTS(SELECT 1 FROM jsonb_array_elements((SELECT target_payload FROM wholesale_ingest.onboarding_promotion_parts WHERE promotion_id=pid AND entity='public.leads')) v WHERE NOT EXISTS(SELECT 1 FROM public.leads a WHERE (to_jsonb(a)-ARRAY['total_score','updated_at','retention_rule','retention_action','retention_due_at','retention_deletable','retention_reason'])=(v-ARRAY['total_score','updated_at','retention_rule','retention_action','retention_due_at','retention_deletable','retention_reason']))) THEN RAISE EXCEPTION 'Transferred row mismatch: public.leads'; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements((SELECT target_payload FROM wholesale_ingest.onboarding_promotion_parts WHERE promotion_id=pid AND entity='public.tasks')) v WHERE NOT EXISTS(SELECT 1 FROM public.tasks a WHERE (to_jsonb(a))=(v))) THEN RAISE EXCEPTION 'Transferred row mismatch: public.tasks'; END IF;
