 IF EXISTS(SELECT 1 FROM jsonb_array_elements((SELECT source_payload FROM wholesale_ingest.onboarding_promotion_parts WHERE promotion_id=pid AND entity='existing_leads')) v
 JOIN public.leads l ON l.id=(v->>'id')::uuid WHERE
 (to_jsonb(l)-ARRAY['assigned_to','updated_at','retention_rule','retention_action','retention_due_at','retention_deletable','retention_reason'])
 IS DISTINCT FROM (v-ARRAY['assigned_to','updated_at','retention_rule','retention_action','retention_due_at','retention_deletable','retention_reason'])
 OR l.assigned_to IS DISTINCT FROM coalesce((v->>'assigned_to')::uuid,owner_id))
 THEN RAISE EXCEPTION 'Existing CRM content or owner changed unexpectedly'; END IF;
 IF EXISTS(SELECT 1 FROM wholesale_ingest.properties p JOIN public.leads l ON l.id=p.lead_id
 WHERE p.county='Collin' AND (l.assigned_to IS NULL OR NOT EXISTS(SELECT 1 FROM public.tasks t WHERE t.lead_id=l.id AND t.assigned_to=l.assigned_to AND t.type='follow_up')))
 THEN RAISE EXCEPTION 'Lead owner or follow-up missing'; END IF;
 IF (SELECT count(*) FROM wholesale_ingest.properties)<>78 OR (SELECT count(*) FROM wholesale_ingest.contacts)<>481
 OR (SELECT count(*) FROM wholesale_ingest.skip_trace_requests WHERE state='completed')<>77
 OR (SELECT count(*) FROM wholesale_ingest.contacts WHERE dnc_status='listed')<>146
 OR (SELECT count(*) FROM wholesale_ingest.contacts WHERE dnc_status='unknown')<>335
 THEN RAISE EXCEPTION 'Promoted graph counts changed'; END IF;
 PERFORM public.list_pipeline_snapshot(current_date,0);
 PERFORM public.propstream_handoff_snapshot(owner_id,0);
 PERFORM public.foreclosure_capture_status(owner_id);
 UPDATE wholesale_ingest.onboarding_promotions SET state='complete',completed_at=now(),
 result=jsonb_build_object('properties',78,'new_leads',74,'existing_leads',4,'source_records',164,'original_tasks',77,'completed_traces',77,'contacts',481,'dnc_listed',146,'dnc_unknown',335,'dispatch',false,'outreach_authorized',false)
 WHERE id=pid;
END $promotion$;
COMMIT;
